insert into public.report_narratives (id, report_id, building_id, section_key, sort_order, heading, body) values
  ('fcc31dab-667a-5001-90ba-7c7afb2271a5', '83d6d2c5-50fe-53f7-9976-3f1157270baf', '63345a91-6706-5cf3-b26e-80174c36b2b5', 'structural', 0, 'STRUCTURAL REPAIRS', 'Plaster band at Shoprite is now complete. Urgent Structural repairs need to be completed behind Clicks and Pircard Rebel needs to take place as the wall shifts leading to internal partitions falling off.'),
  ('580958e0-ad97-59cc-acf1-b3b64d834124', '83d6d2c5-50fe-53f7-9976-3f1157270baf', '63345a91-6706-5cf3-b26e-80174c36b2b5', 'cosmetic', 1, 'COSMETIC REPAIRS', 'Tiles need to be installed at the wall against Standard Bank. Quotes received form D en G.'),
  ('83ffeccb-95a3-59b8-8125-c4dbcd95efed', '83d6d2c5-50fe-53f7-9976-3f1157270baf', '63345a91-6706-5cf3-b26e-80174c36b2b5', 'roofing', 2, 'ROOFING AND WATERPROOFING', 'Water proof coating needs to be done at shoprite liquor roof slab. ( to be done by projects)'),
  ('e4a186a3-1db7-5263-9f42-15b79df13abb', '83d6d2c5-50fe-53f7-9976-3f1157270baf', '63345a91-6706-5cf3-b26e-80174c36b2b5', 'gutters', 3, 'GUTTERS & DOWNPIPES', 'Downpipes around rank and Mason st needs attention to be done by handyman'),
  ('48f9ce4c-d582-5a7d-858f-80689cc45d3f', '83d6d2c5-50fe-53f7-9976-3f1157270baf', '63345a91-6706-5cf3-b26e-80174c36b2b5', 'electrical', 4, 'ELECTRICAL, GENERATORS AND TRANSFORMERS', 'Infrared scanning done in February 2025, no other issues to report. Installation of drip treys project and oil sample testing done,next test to be done  September 2026.'),
  ('9e3aa248-b4c0-5d85-8326-8749c69cb4df', '83d6d2c5-50fe-53f7-9976-3f1157270baf', '63345a91-6706-5cf3-b26e-80174c36b2b5', 'plumbing', 5, 'PLUMBING, BOREHOLES AND JOJO TANKS', 'Borehole is now working properly. Last service was in October. More meters to be installed. We are waiting for a quotation and parts. Water sampling took place in October 2025'),
  ('b577cb07-a6de-589c-a5f2-2d6dfbc66ea4', '83d6d2c5-50fe-53f7-9976-3f1157270baf', '63345a91-6706-5cf3-b26e-80174c36b2b5', 'solar', 6, 'SOLAR MAINTENANCE', 'One broken solar panel, call has been logged, awaiting contractor to replace.'),
  ('8ecffe35-f5f9-53c1-8cb0-8b62c8dcd9bd', '83d6d2c5-50fe-53f7-9976-3f1157270baf', '63345a91-6706-5cf3-b26e-80174c36b2b5', 'fire', 7, 'FIRE PROTECTION', 'Some fire equipment has leaks after the KFC sprinkler installation this has been escallated to Secure fire to be sorted before 20/11/25'),
  ('44ff4ed1-d475-5f94-b016-f784ca4bce17', '83d6d2c5-50fe-53f7-9976-3f1157270baf', '63345a91-6706-5cf3-b26e-80174c36b2b5', 'tenant_movements', 8, 'TENANT MOVEMENTS', 'New Tenants KFC & Sanlam are now operational. All signage installation have been approved by the landlord.'),
  ('951ec815-5ecc-5610-8d7b-7ddc4483b2aa', '83d6d2c5-50fe-53f7-9976-3f1157270baf', '63345a91-6706-5cf3-b26e-80174c36b2b5', 'hvac', 9, 'HVAC', 'All units are in good working condition. Monthly maintenance services are being carried out by Total comfort.'),
  ('0b8cb6ac-17e8-508a-a365-0af8fbd03721', '83d6d2c5-50fe-53f7-9976-3f1157270baf', '63345a91-6706-5cf3-b26e-80174c36b2b5', 'signage', 10, 'SIGNAGE', 'All signage are in good working condition .')
